from pathlib import Path
import json,csv,re
D=Path(__file__).resolve().parent
T=[];I=[];P=[];C=[];B=[]
def ref(key,typ='article',**kw):
 kw.setdefault('note','verified');B.append('@'+typ+'{'+key+',\n'+',\n'.join('  '+k+' = {'+str(v)+'}' for k,v in kw.items())+'\n}\n')
def talk(rec,date,speaker,pages,title,summary,kind='talk'):
 T.append(dict(record=rec,date=date,speaker=speaker,pages=pages,title=title,summary=summary,kind=kind))
def item(rec,pages,kind,title,notes,statement,cls,fate,refs=(),reconstruction='',literal='correct with missing hypotheses',match='exact',verification='read the result',confidence='high',problem='',status='',speaker='',development='annotated',worth=''):
 n=1+sum(x['record']==rec for x in I)
 x=dict(id=f'1982-{rec}.{n}',record=rec,pages=pages,kind=kind,title=title,notes=notes,statement=statement,reconstruction=reconstruction,**{'class':cls},fate=fate,present_status='As of November 2026: '+(status or ('the stated result is established in the specified setting.' if cls in 'ABE' else 'the notebook does not determine a unique proposition whose resolution can be assessed.')),literal_correctness=literal,publication_match=match,verification=verification,development=development,problem=problem,worth=worth,refs=list(refs),confidence=confidence)
 if speaker:x['speaker']=speaker
 I.append(x);return x['id']
def correction(page,place,reads,should,evidence,applies='both',typ='faithful_error'):
 C.append(dict(page=page,place=place,transcription_reads=reads,should_read=should,evidence=evidence,applies_to=applies,type=typ))
def save():
 for name,rows in [('talks',T),('items',I),('problems',P)]: (D/(name+'.json')).write_text(json.dumps(rows,ensure_ascii=False,indent=2)+'\n')
 with (D/'corrections.csv').open('w',newline='') as f:
  w=csv.DictWriter(f,fieldnames=['page','place','transcription_reads','should_read','evidence','applies_to','type']);w.writeheader();w.writerows(C)
 (D/'references.bib').write_text('\n'.join(B))
 print(len(T),'records',len(I),'items',len(P),'problems',len(C),'corrections')
